#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Argus dedicated browser identity.
# No credentials are read, stored or written by this wizard (no .env writes).
# ──────────────────────────────────────────────────────────────────────────

# Chrome 136+ ignores --remote-debugging-port / --remote-debugging-pipe when
# pointed at the DEFAULT user-data-dir; they must come with a non-standard
# --user-data-dir. Source: https://developer.chrome.com/blog/remote-debugging-port
# (Chrome blog, "Changes to remote debugging switches to improve security").
# Playwright's launchPersistentContext also needs its own dir, so we create one.

TOTAL_STAGES=7
DIR="${ARGUS_CHROME_DIR:-$HOME/.local/share/argus/chrome}"
CHROME=""
LAUNCHER="$HOME/.local/share/applications/argus-chrome.desktop"

# gate "question": y continues; n lets you redo the stage's check or abort.
gate() {
  while ! confirm "$1"; do
    warn "Not confirmed. Fix it, then answer y. (Ctrl-C to stop; re-run is safe.)"
  done
}

# chrome_running: true if any Chrome process owns $DIR.
chrome_running() {
  pgrep -f -- "--user-data-dir=$DIR" >/dev/null 2>&1 || [[ -L "$DIR/SingletonLock" ]]
}

banner "Argus dedicated browser identity"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Detect Chrome"
for c in google-chrome-stable google-chrome chromium-browser chromium; do
  if command -v "$c" >/dev/null 2>&1; then CHROME=$(command -v "$c"); break; fi
done
if [[ -z "$CHROME" ]]; then
  warn "No Chrome/Chromium found. Install Google Chrome (the Claude in Chrome extension supports Chrome/Edge, not Firefox)."
  say "Fedora: https://www.google.com/chrome/ (.rpm), then re-run."
  exit 1
fi
VER=$("$CHROME" --version 2>/dev/null || echo "unknown")
say "Found: $CHROME"
say "Version: $VER"
MAJOR=$(grep -oE '[0-9]+' <<<"$VER" | head -n1 || true)
if [[ "$CHROME" == *chromium* ]]; then
  warn "Chromium may not run the Claude in Chrome extension (Chrome Web Store build targets Chrome). Prefer Google Chrome."
fi
if [[ -n "${MAJOR:-}" ]] && (( MAJOR < 136 )); then
  note "Chrome < 136: default-dir debugging would still work, but we use a separate dir anyway."
fi
gate "Is this the Chrome you want Argus to use?"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Create the separate user-data-dir"
say "Chrome 136+ ignores remote-debugging switches on the default data dir, and"
say "Playwright's persistent context needs its own dir. So: a fresh, separate one,"
say "NOT a profile inside ~/.config/google-chrome."
note "Source: developer.chrome.com/blog/remote-debugging-port"
say "Dir: $DIR   (override: ARGUS_CHROME_DIR=/path ./setup-argus-browser.sh)"
if [[ "$DIR" == "$HOME/.config/google-chrome"* || "$DIR" == "$HOME/.config/chromium"* ]]; then
  warn "That is Chrome's default location. Refusing."; exit 1
fi
if chrome_running; then
  warn "A Chrome is already using $DIR. Quit it first."; gate "Quit it. Continue?"
fi
mkdir -p "$DIR"
chmod 700 "$DIR"
[[ -d "$DIR" && -w "$DIR" ]] && say "$(printf '%s✓%s dir exists and is writable' "$GREEN" "$RESET")"
note "It will hold the X login cookies. Keep it out of git and backups you share."
gate "Directory created. Continue?"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Launch Chrome; install Claude in Chrome"
say "Launching Chrome on the Argus dir (no debugging port opened)."
nohup setsid "$CHROME" --user-data-dir="$DIR" --no-first-run --no-default-browser-check \
  "https://claude.ai/chrome" >/dev/null 2>&1 &
sleep 3
step "In THAT window, install the Claude in Chrome extension (the page opened offers it, or search the Chrome Web Store)."
step "Open the extension and sign in to the SAME claude.ai org Claude Code uses."
step "Do NOT sign in to Chrome with a Google account unless you want sync; not needed."
if [[ -d "$DIR/Default/Extensions" ]] && [[ -n "$(ls -A "$DIR/Default/Extensions" 2>/dev/null)" ]]; then
  say "$(printf '%s✓%s an extension is installed in the Argus dir' "$GREEN" "$RESET")"
else
  note "Extension not detected on disk yet (Chrome may not have flushed it); your y/n below decides."
fi
gate "Extension installed and signed in to the right org (Claude Code's)?"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Create the Argus X account and log in"
say "A NEW X account used only by Argus. Never your personal one."
open_url "https://x.com/i/flow/signup"
note "xdg-open uses your default browser; paste the link into the ARGUS Chrome window if that is a different browser."
step "Sign up in the Argus Chrome window with a dedicated email and phone."
step "Settings > Security and account > Security > Two-factor authentication: enable an authenticator app (not SMS)."
step "Give it a plausible profile: display name, avatar, short bio, follow a few real accounts."
step "Log out and in once, tick 'remember me' / stay logged in, then confirm x.com/home loads."
warn "This wizard never sees or stores any password, phone, email or 2FA seed. Keep them in your password manager."
gate "X account exists, 2FA on, and you are logged in with login remembered?"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Pre-approve x.com in the extension"
say "So manual checks do not stall on a permission prompt."
step "In the Argus Chrome window: puzzle icon > Claude > Settings/Options > Site permissions."
step "Allow x.com and twitter.com."
note "If the UI differs from this, look for any per-site allow list in the extension's settings."
gate "x.com and twitter.com allowed in the extension's site permissions?"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Close Chrome cleanly"
say "Only one process may own the dir; Playwright cannot start while Chrome holds it."
step "Quit Chrome fully in the Argus window (menu > Exit, or Ctrl+Q). Not just closing the tab."
while chrome_running; do
  warn "Chrome still holds $DIR."
  pause "Quit it, then press Enter to re-check"
  sleep 1
done
say "$(printf '%s✓%s nothing holds the dir' "$GREEN" "$RESET")"
say "Profile dir: $DIR"
say "Playwright will reuse this dir (launchPersistentContext) to stay logged in."
gate "Chrome closed and the path noted?"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Optional: 'Argus Chrome' desktop launcher"
if confirm "Create a launcher for manual checks in this dir?"; then
  mkdir -p "$(dirname "$LAUNCHER")"
  cat > "$LAUNCHER" <<DESKTOP
[Desktop Entry]
Type=Application
Name=Argus Chrome
Comment=Dedicated Chrome identity for Argus
Exec=$CHROME --user-data-dir=$DIR --no-first-run --no-default-browser-check
Icon=google-chrome
Terminal=false
Categories=Network;WebBrowser;
DESKTOP
  chmod 644 "$LAUNCHER"
  command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database "$(dirname "$LAUNCHER")" >/dev/null 2>&1 || true
  if [[ -f "$LAUNCHER" ]]; then say "$(printf '%s✓%s wrote %s' "$GREEN" "$RESET" "$LAUNCHER")"; fi
  warn "Quit it before any Playwright run; one process per dir."
else
  note "Skipped. Launch manually: $CHROME --user-data-dir=$DIR"
fi
pause "Press Enter to finish"

finish
say "Argus Chrome dir: $DIR"
say "Playwright will reuse it as its persistent userDataDir; keep Chrome closed during runs."
printf '\n'
